			name:     "refill capped at capacity",
			capacity: 3,
			rate:     10,
			advances: []time.Duration{0, 0, 0, 0, 10 * time.Second, 0, 0, 0},
			n:        1,
			want:     []bool{true, true, true, false, true, true, true, false},
		},
		{
			name:     "allowN multiple tokens",
			capacity: 10,
			rate:     2,
			advances: []time.Duration{0, 0, time.Second, 0},
			n:        3,
			want:     []bool{true, true, true, false},
		},
		{
			name:     "n zero always allowed",
			capacity: 1,
			rate:     1,
			advances: []time.Duration{0, 0},
			n:        0,
			want:     []bool{true, true},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clock := &fakeClock{t: time.Unix(0, 0)}
			l, err := NewLimiter(tt.capacity, tt.rate, clock)
			if err != nil {
				t.Fatal(err)
			}
			for i, adv := range tt.advances {
				clock.Advance(adv)
				got := l.AllowN(tt.n)
				if got != tt.want[i] {
					t.Fatalf("step %d: got %v, want %v", i, got, tt.want[i])
				}
			}
		})
	}
}
